def compute(vars):
    revenue_growth_2019 = vars["v1"]
    revenue_growth_2018 = vars["v2"]
    change = revenue_growth_2019 - revenue_growth_2018

    return {
        "value": change,
        "trace": {
            "revenue_growth_2019": revenue_growth_2019,
            "revenue_growth_2018": revenue_growth_2018,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
